3	import { PropertyFilterOption, SubcategoriesApi } from '../../../core/api/subcategories.api';
4	
5	export type PropertyFilterSelection = Record<string, string[]>;
6	
7	@Component({
8	  selector: 'app-property-filter',
9	  imports: [],
10	  templateUrl: './property-filter.html',
11	  styleUrl: './property-filter.scss',
12	})
13	export class PropertyFilter {
14	  private readonly subcategoriesApi = inject(SubcategoriesApi);
15	
16	  readonly subcategoryId = input<string | null>(null);
17	  readonly selection = input<PropertyFilterSelection>({});
18	  readonly disabled = input(false);
19	  readonly selectionChange = output<PropertyFilterSelection>();
20	
21	  protected readonly options = signal<PropertyFilterOption[]>([]);
22	  protected readonly loading = signal(false);
23	  protected readonly error = signal(false);
24	
25	  constructor() {
26	    effect(() => {
27	      const subcategoryId = this.subcategoryId();
28	      if (subcategoryId === null) {
29	        this.options.set([]);
30	        return;
31	      }
32	
33	      this.loading.set(true);
34	      this.error.set(false);
35	      this.subcategoriesApi.getProperties(subcategoryId).subscribe({
36	        next: (options) => {
37	          if (this.subcategoryId() !== subcategoryId) {
38	            return;
39	          }
40	          this.options.set(options);
41	          this.loading.set(false);
42	        },
43	        error: () => {
44	          if (this.subcategoryId() !== subcategoryId) {
45	            return;
46	          }
47	          this.options.set([]);
48	          this.loading.set(false);
49	          this.error.set(true);
50	        },
51	      });
52	    });
53	  }
54	
55	  protected isChecked(name: string, value: string): boolean {
56	    return this.selection()[name]?.includes(value) ?? false;
57	  }
58	
59	  protected toggleValue(name: string, value: string, checked: boolean): void {
60	    const next: PropertyFilterSelection = { ...this.selection() };
61	    const values = next[name] ?? [];
62	
63	    if (checked) {
64	      next[name] = [...values, value];
65	    } else {
66	      const remaining = values.filter((v) => v !== value);
67	      if (remaining.length > 0) {
68	        next[name] = remaining;
69	      } else {
70	        delete next[name];
71	      }
72	    }
73	
74	    this.selectionChange.emit(next);
75	  }
76	}
