  <p class="product-detail__error">Das Produkt konnte nicht geladen werden. Bitte versuchen Sie es später erneut.</p>
}

@if (product(); as product) {
  <article class="product-detail">
    <h1 class="product-detail__name">{{ product.name }}</h1>
    <p class="product-detail__category">{{ product.categoryName }} / {{ product.subcategoryName }}</p>
    <p class="product-detail__description">{{ product.description }}</p>

    @if (product.properties.length > 0) {
      <dl class="product-detail__properties">
        @for (property of product.properties; track property.name) {
          <dt>{{ property.name }}</dt>
          <dd>{{ property.value }}</dd>
        }
      </dl>
    }

    <p class="product-detail__rating">
      @if (product.averageRating !== null) {
        {{ product.averageRating | number: '1.1-1' }} ({{ product.ratingCount }} Bewertungen)
      } @else {
        Noch keine Bewertungen
      }
    </p>

    @if (product.offers.length > 0) {
      <ul class="product-detail__offers">
        @for (offer of product.offers; track offer.supplierId) {
          <li class="product-detail__offer">
            <span class="product-detail__offer-supplier">{{ offer.supplierName }}</span>
            <span class="product-detail__offer-price">{{ offer.price | number: '1.2-2' }} €</span>
          </li>
        }
      </ul>
    } @else {
      <p class="product-detail__no-offers">Aktuell kein Lieferant verfügbar.</p>
    }
  </article>
}

